const first = $input.first().json;
const raw = typeof first.data === 'string' ? first.data : '';
const lines = raw.split('\n').map(l => l.trim()).filter(l => l.length > 0 && l.length <= 2048 && l.indexOf('http') === 0);
const unique = Array.from(new Set(lines)).slice(0, 10000);
return [{ json: { source: 'openphish', fetched_at: new Date().toISOString(), count: unique.length, urls: unique } }];
